<?php get_header(); ?><main class="content-area"><div class="container"><?php if(have_posts()): while(have_posts()): the_post(); ?><article class="post"><h1><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h1><div class="post-meta"><?php echo esc_html(get_the_date()); ?></div><?php the_excerpt(); ?></article><?php endwhile; the_posts_pagination(); else: ?><h1>No posts found</h1><?php endif; ?></div></main><?php get_footer(); ?>